const { PrismaClient } = require('@prisma/client');
const fs = require('fs');

const prisma = new PrismaClient();

const xprisma = prisma.$extends({
  result: {
    user: {
      fullLabel: {
        needs: { name: true, email: true },
        compute(user) {
          return `${user.name} <${user.email}>`;
        }
      }
    }
  }
});

async function main() {
  const email = 'computed@example.com';
  const name = 'Computed';

  // Cleanup existing user if any
  try {
    await prisma.user.delete({ where: { email } }).catch(() => {});
  } catch (err) {
    // Ignore error if user doesn't exist
  }

  // Create a user
  await xprisma.user.create({
    data: { email, name }
  });

  // Query it with xprisma
  const result = await xprisma.user.findUnique({
    where: { email }
  });

  // Write the result to computed_result.json
  fs.writeFileSync('/home/user/myproject/computed_result.json', JSON.stringify(result, null, 2));

  console.log('User with computed field:');
  console.log(JSON.stringify(result, null, 2));
}

main()
  .catch((e) => {
    console.error(e);
    process.exit(1);
  })
  .finally(async () => {
    await prisma.$disconnect();
  });

